find:
let first = match input_names.entry(input_name) {
    Entry::Occupied(slot) => slot.into_mut(),
    Entry::Vacant(slot) => {
        slot.insert(input.clone());
        local_inputs.push(input);
        continue;
    }
};

replace:
let Some(first) = local_inputs.iter().find(|first| first.input.name == input_name) else {
    local_inputs.push(input);
    continue;
};
